using System.IO;
using System.Text.Json;
using Orbit.Core;
namespace OrbitLauncher;
public partial class MainWindow {
 async Task CheckQuickLoaderUiAsync(string root){var report=new List<string>();void Check(bool ok,string title){if(!ok)throw new Exception(title);report.Add("PASS "+title);}async Task<JsonElement> Js(string js)=>JsonDocument.Parse(await brawlBrowser!.CoreWebView2.ExecuteScriptAsync(js)).RootElement.Clone();
 try{NicknameBox.Text="Player";settings.Theme="brawl stars";ApplyTheme();Navigate("Home");await brawlInitTask;await brawlPageReady.Task.WaitAsync(TimeSpan.FromSeconds(35));await LoadCatalogAsync();selectedChoice=new VersionEntry("1.12.2","Vanilla","1.12.2",8);SyncBrawlState();await Task.Delay(1200);
 foreach(string loader in new[]{"Fabric","Forge"}){await Js("document.querySelector('.lobby-mode').click()");await Task.Delay(250);await Js("document.querySelector('.orbit-quick-actions ."+loader.ToLowerInvariant()+"').click()");await Task.Delay(150);Check((await Js("!!document.querySelector('[aria-label=\"Quick loader\"]')")).GetBoolean(),loader+" dialog opens");for(int i=0;i<200&&(quickCatalogLoading||quickCatalogLoader!=loader);i++)await Task.Delay(100);SyncBrawlState();await Task.Delay(400);Check(quickCatalogError==""&&!quickCatalogLoading,loader+" supported catalog loaded");var state=await Js("(()=>{const d=document.querySelector('[aria-label=\"Quick loader\"]'),s=d.querySelector('select');return {options:[...s.options].map(o=>o.value),selected:s.value,enabled:!d.querySelector('button.primary').disabled}})()");var options=state.GetProperty("options").EnumerateArray().Select(x=>x.GetString()).ToArray();Check(options.Contains("1.21.1")&&options.Length>0,loader+" offers supported Minecraft releases");if(loader=="Fabric")Check(!options.Contains("1.12.2")&&state.GetProperty("selected").GetString()!="1.12.2","Fabric never offers unsupported 1.12.2 and selects a valid replacement");else Check(options.Contains("1.12.2"),"Forge retains supported legacy 1.12.2");Check(state.GetProperty("enabled").GetBoolean(),loader+" install enabled only after compatible selection");using(var image=File.Create(Path.Combine(root,"quick-"+loader.ToLowerInvariant()+"-fixed.png")))await brawlBrowser!.CoreWebView2.CapturePreviewAsync(Microsoft.Web.WebView2.Core.CoreWebView2CapturePreviewImageFormat.Png,image);await Js("document.querySelector('.orbit-close').click()");await Task.Delay(250);}
 Check((await Js("window.orbitErrors.length===0")).GetBoolean(),"No React errors after loader catalog updates");
 }finally{File.WriteAllLines(Path.Combine(root,"quick-loader-ui-checks.txt"),report);}
 }
}
